def caesar_cipher(text, shift):
    encrypted = []
    for c in text:
        if c.isupper():
            encrypted_char = chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        elif c.islower():
            encrypted_char = chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        else:
            encrypted_char = c
        encrypted.append(encrypted_char)
    return ''.join(encrypted)

def check_key(dictionary, key):
    if key in dictionary:
        return True
    for value in dictionary.values():
        if isinstance(value, dict):
            if check_key(value, key):
                return True
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict) and check_key(item, key):
                    return True
    return False

def find_smallest_missing_positive(nums: list[int]) -> int:
    positive_nums: set[int] = {num for num in nums if num > 0}
    candidate: int = 1
    while candidate in positive_nums:
        candidate += 1
    return candidate

def calculate_hashcode(message):
    total = 0
    for c in message:
        if c == ' ':
            total += 26
        else:
            total += ord(c.upper()) - ord('A')
    return total

def max_subarray_sum(numbers, k):
    current_sum = sum(numbers[:k])
    max_sum = current_sum
    for i in range(k, len(numbers)):
        current_sum += numbers[i] - numbers[i - k]
        if current_sum > max_sum:
            max_sum = current_sum
    return max_sum
